#include <stdexcept>

// Divides, refusing a zero divisor.
double safeDivide(double a, double d)
{
    if (d == 0) throw std::domain_error("division by zero");
    return a / d;
}

double area(double r, double k)
{
    return k * square(r) + legacy(r);
}

